172	/**
173	 * Simulate token-by-token streaming from a cached result.
174	 * Emits chunks of ~20 chars with a small delay between each,
175	 * so the client sees the same partial-JSON rendering behavior
176	 * as a real LLM stream.
177	 */
178	async function simulateStreamFromCache(
179	  controller: ReadableStreamDefaultController<Uint8Array>,
180	  text: string,
181	  usage: LlmCallUsage,
182	): Promise<void> {
183	  const CHUNK_SIZE = 20;
184	  const DELAY_MS = 15;
185	
186	  for (let i = 0; i < text.length; i += CHUNK_SIZE) {
187	    const chunk = text.slice(i, i + CHUNK_SIZE);
188	    controller.enqueue(sseEvent("token", { text: chunk }));
189	    await new Promise((resolve) => setTimeout(resolve, DELAY_MS));
190	  }
191	
192	  controller.enqueue(sseEvent("done", { text, usage }));
193	}
