205	async function streamAnthropic(
206	  controller: ReadableStreamDefaultController<Uint8Array>,
207	  opts: StreamProviderOptions,
208	): Promise<void> {
209	  const client = getAnthropicClient(opts.apiKey);
210	  const start = Date.now();
211	
212	  const stream = client.messages.stream({
213	    model: opts.model,
214	    max_tokens: opts.maxTokens,
215	    system: opts.systemPrompt,
216	    messages: [{ role: "user", content: opts.userContent }],
217	  });
218	
219	  let accumulated = "";
220	
221	  stream.on("text", (text) => {
222	    accumulated += text;
223	    controller.enqueue(sseEvent("token", { text }));
224	  });
225	
226	  const finalMessage = await stream.finalMessage();
227	  const latencyMs = Date.now() - start;
228	
229	  const usage: LlmCallUsage = {
230	    provider: "anthropic",
231	    model: opts.model,
232	    inputTokens: finalMessage.usage.input_tokens,
233	    outputTokens: finalMessage.usage.output_tokens,
234	    costUsd: computeCost(opts.model, finalMessage.usage.input_tokens, finalMessage.usage.output_tokens),
235	    latencyMs,
236	  };
237	
238	  await recordAndCache(opts.endpoint, usage, accumulated, opts.cacheHash);
239	  controller.enqueue(sseEvent("done", { text: accumulated, usage }));
240	  controller.close();
241	}
